mapper.update:
UPDATE lambda_assignments
SET schedule_last_date = #{lastDate},
    schedule_next_date = #{nextDate}
WHERE lambda_assignment_id = #{lambdaAssignmentId}

UPDATE lambda_assignments
SET schedule_last_date = #{lastDate},
    schedule_next_date = #{nextDate}
WHERE lambda_assignment_id = #{lambdaAssignmentId}
  AND ((#{expectedLastDate} IS NULL AND schedule_last_date IS NULL) OR schedule_last_date = #{expectedLastDate})
  AND ((#{expectedNextDate} IS NULL AND schedule_next_date IS NULL) OR schedule_next_date = #{expectedNextDate})

mapper.select:
SELECT EXISTS (
SELECT 1
FROM location_devices ld
JOIN devices d ON d.device_uuid = ld.device_uuid
JOIN locations l ON l.location_id = ld.location_id
WHERE d.device_uuid = #{deviceId}
    AND ld.location_id = #{locationId}
    AND (ld.end_date IS NULL OR ld.end_date > NOW())
    AND l.deleted_at IS NULL
)

mapper.update:
UPDATE lambda_latest_runs
SET pending_count = #{pendingCount}, next_input_number = #{nextInputNumber}
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND invocation_lane = #{lane}

UPDATE lambda_latest_runs
SET invocation_gen = invocation_gen + 1, is_started = true
    , aws_request_id = #{awsRequestId}
    , aws_log_stream = #{awsLogStream}
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND invocation_lane = #{lane}
    AND run_id = #{runId} AND invocation_gen = #{invocationGen}

UPDATE lambda_latest_runs
SET invocation_gen = invocation_gen + 1, is_started = false
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND invocation_lane = #{lane}

UPDATE lambda_latest_runs
SET invocation_gen = #{invocationGen}, is_started = false,
    aws_request_id = NULL,
    aws_log_stream = NULL,
    expiry_date = #{expiryDate}
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND invocation_lane = #{lane}

UPDATE lambda_latest_runs
SET prev_run_id = run_id, run_id = 0,
    pending_count = 0, next_input_number = NULL
WHERE lambda_assignment_id = #{lambdaAssignmentId} AND invocation_lane = #{lane}

    AND run_id = #{prevRunId}
    AND (pending_count = 0 OR next_input_number IS NULL)

mapper.select:
SELECT input_number, input_size,
    CASE WHEN is_large_input THEN large_input_data ELSE SUBSTR(input_data, 1, input_size) END AS "data"
FROM lambda_pending_inputs_p
WHERE part IN (${partitions})
    AND lambda_assignment_id = #{lambdaAssignmentId}
    AND lane = #{lane}
    AND input_number >= #{nextInputNumber}

    ORDER BY input_number

LIMIT #{maxCount}

SELECT v.original_size, v.value, v.large_value
FROM lambda_assignment_vars v
JOIN lambda_assignments i ON i.lambda_assignment_id = v.lambda_assignment_id
    AND i.private_variable_generation = v.generation
WHERE v.lambda_assignment_id = #{lambdaAssignmentId}
    AND v.generation = #{generation}
    AND v.variable_name = #{name}

mapper.delete:
DELETE FROM lambda_assignment_vars
WHERE lambda_assignment_id = #{lambdaAssignmentId}
AND generation = #{generation}
AND variable_name = #{name}

mapper.insert:
INSERT INTO lambda_assignment_vars
    (lambda_assignment_id, generation, variable_name, update_date, original_size, value, large_value)
SELECT lambda_assignment_id, #{generation}, #{name}, #{updateDate}, #{originalSize}, #{smallValue}, #{largeValue}
FROM lambda_assignments
WHERE lambda_assignment_id = #{lambdaAssignmentId}
    AND private_variable_generation = #{generation}

mapper.update:
UPDATE lambda_assignment_vars
SET update_date = #{updateDate}, original_size = #{originalSize}, value = #{smallValue}, large_value = #{largeValue}
WHERE lambda_assignment_id = #{lambdaAssignmentId}
    AND generation = #{generation}
    AND variable_name = #{name}
    AND EXISTS (
        SELECT 1
        FROM lambda_assignments
        WHERE lambda_assignment_id = #{lambdaAssignmentId}
            AND private_variable_generation = #{generation})

mapper.select:
SELECT private_variable_generation
FROM lambda_assignments
WHERE lambda_assignment_id = #{lambdaAssignmentId}

mapper.update:
UPDATE lambda_assignments
SET private_variable_generation = #{generation}
WHERE lambda_assignment_id = #{lambdaAssignmentId}
    AND private_variable_generation < #{generation}

mapper.select:
SELECT original_size, value
FROM lambda_location_vars
WHERE location_id = #{locationId} AND variable_name = #{name}

mapper.delete:
DELETE FROM lambda_location_vars
WHERE location_id = #{locationId}
AND variable_name = #{name}

mapper.update:
UPDATE lambda_location_vars
SET update_date = #{updateDate}, original_size = #{originalSize}, value = #{smallValue}
WHERE location_id = #{locationId} AND variable_name = #{name}
